name: story-to-spec
description: Convert US-01, US-02, or US-03 from the multi-country insurance technical assessment into a testable, source-grounded specification before implementation.
---

# Story to Specification

## Inputs
- Original assessment: `requirements/technical-assessment.pdf`.
- User-story identifier and source text.
- `AGENTS.md` and any applicable approved ADRs.

## Repeatable procedure
1. Extract source-stated story, business rules and acceptance scenarios with page references.
2. Build a requirement-to-observable-behavior-to-test traceability table.
3. Define proposed Strapi/Angular contracts and specify loading, empty, invalid and failure states.
4. Identify missing decisions. Label each as **Question** or **Proposal**, never as a verbatim source requirement.
5. Write verifiable Given/When/Then cases covering both countries when applicable.
6. Save to `spec/US-XX.md` with status **Pending human approval**.
7. Request a human decision. If rejected, document feedback and revise the spec, retaining the review record.

## Expected result
A reviewable, testable and traceable specification. No application implementation and no self-approval.
import { HttpClient } from '@angular/common/http';
import { inject, Injectable, InjectionToken, signal } from '@angular/core';
import {
  decodeForm,
  isFieldKind,
  isKindValue,
  isRecord,
  isSafeId,
  reconcileDraft,
  validateField,
  type Country,
  type DraftEntry,
  type FormDefinition,
  type QuoteDraft,
} from '@quote/contract';
import type { Subscription } from 'rxjs';

type LoadState =
  | { phase: 'idle' }
  | { phase: 'loading' | 'unavailable'; country: Country }
  | { phase: 'ready'; country: Country; form: FormDefinition; validation?: DraftValidation };

type DraftValidation = { date: string; invalidFields: readonly string[] };

export const QUOTE_CLOCK = new InjectionToken<() => Date>('quote calendar clock', {
  providedIn: 'root',
  factory: () => () => new Date(),
});

function civilDate(now: Date): string {
  return `${now.getFullYear()}-${now.getMonth() + 1}-${now.getDate()}`;
}

function evaluate(form: FormDefinition, draft: QuoteDraft, now: Date): DraftValidation {
  const invalidFields = form.fields
    .filter((field) => validateField(field, draft[field.id]?.value, now).length)
    .map((field) => field.id);
  return { date: civilDate(now), invalidFields };
}

function storageKey(country: Country) {
  return `quote-draft-v1:${country}`;
}

function restore(country: Country): QuoteDraft {
  try {
    const text = sessionStorage.getItem(storageKey(country));
    if (!text || text.length > 100_000) return {};
    const snapshot: unknown = JSON.parse(text);
    if (
      !isRecord(snapshot) ||
      snapshot['version'] !== 1 ||
      snapshot['country'] !== country ||
      !isRecord(snapshot['draft'])
    )
      return {};
    const entries = Object.entries(snapshot['draft']);
    if (entries.length > 40) return {};
    const draft: [string, DraftEntry][] = [];
    for (const [key, entry] of entries) {
      if (
        !isSafeId(key) ||
        !isRecord(entry) ||
        !isFieldKind(entry['kind']) ||
        (entry['value'] !== null && !isKindValue(entry['kind'], entry['value']))
      )
        return {};
      draft.push([key, { kind: entry['kind'], value: entry['value'] }]);
    }
    return Object.fromEntries(draft);
  } catch {
    return {};
  }
}

import { Routes } from '@angular/router';
import { CountryPicker } from './country-selection/country-picker';
import { QuotePage } from './quote/quote-page';

export const routes: Routes = [
  {
    path: '',
    pathMatch: 'full',
    component: CountryPicker,
    title: 'Elige un país · Seguro de auto',
  },
  { path: ':country/quote/:step', component: QuotePage, title: 'Cotización · Seguro de auto' },
  {
    path: '**',
    component: CountryPicker,
    data: { unsupported: true },
    title: 'País no disponible · Seguro de auto',
  },
];

